module pickle_sandwich (\n    input [31:0] s,\n    input [31:0] r,\n    input [3:0] n,\n    input [6:0] z,\n    output reg [3:0] result\n);\n    \n    localparam [31:0] THRESH_1 = 32'h00010000;\n    localparam [31:0] THRESH_2 = 32'h00020000;\n    localparam [31:0] THRESH_3 = 32'h000228D6;\n    localparam [31:0] THRESH_4 = 32'h00026A0A;\n    localparam [31:0] THRESH_5 = 32'h0002B374;\n    localparam [31:0] THRESH_6 = 32'h00030000;\n    \n    reg [3:0] max_by_area;\n    reg [3:0] max_by_packing;\n    \n    wire [70:0] s_sq = s * s;\n    wire [70:0] r_sq = r * r;\n    wire [70:0] numerator = z * s_sq;\n    wire [70:0] denominator = r_sq * 7'd100;\n    \n    wire [70:0] s_scaled = s << 16;\n    \n    wire [70:0] product_r_thresh1 = r * THRESH_1;\n    wire [70:0] product_r_thresh2 = r * THRESH_2;\n    wire [70:0] product_r_thresh3 = r * THRESH_3;\n    wire [70:0] product_r_thresh4 = r * THRESH_4;\n    wire [70:0] product_r_thresh5 = r * THRESH_5;\n    wire [70:0] product_r_thresh6 = r * THRESH_6;\n    \n    always @(*) begin\n        if (denominator == 0) begin\n            max_by_area = 4'd0;\n        end else begin\n            if (numerator / denominator >= 8'd7) begin\n                max_by_area = 4'd7;\n            end else begin\n                max_by_area = (numerator / denominator)[3:0];\n            end\n        end\n    end\n    \n    always @(*) begin\n        if (s_scaled >= product_r_thresh6) begin\n            max_by_packing = 4'd7;\n        end else if (s_scaled >= product_r_thresh5) begin\n            max_by_packing = 4'd5;\n        end else if (s_scaled >= product_r_thresh4) begin\n            max_by_packing = 4'd4;\n        end else if (s_scaled >= product_r_thresh3) begin\n            max_by_packing = 4'd3;\n        end else if (s_scaled >= product_r_thresh2) begin\n            max_by_packing = 4'd2;\n        end else if (s_scaled >= product_r_thresh1) begin\n            max_by_packing = 4'd1;\n        end else begin\n            max_by_packing = 4'd0;\n        end\n    end\n    \n    always @(*) begin\n        result = n;\n        if (max_by_area < result) result = max_by_area;\n        if (max_by_packing < result) result = max_by_packing;\n    end\n\nendmodule